import React from 'react';
import { FaComments, FaRulerCombined, FaDrawPolygon, FaHardHat, FaCheckCircle } from 'react-icons/fa';
import { NEXT_STEPS } from '../../content';
import './nextsteps.css';

const NextSteps: React.FC = () => {
  const getStepIcon = (iconName: string) => {
    switch (iconName) {
      case 'comments': return <FaComments />;
      case 'ruler': return <FaRulerCombined />;
      case 'draw': return <FaDrawPolygon />;
      case 'hardhat': return <FaHardHat />;
      default: return <FaCheckCircle />;
    }
  };

  return (
    <section className="next-steps-section">
      <div className="container">
        <h2 className="section-title-center" dangerouslySetInnerHTML={{ __html: NEXT_STEPS.title }}></h2>
        <p className="section-subtitle-center">{NEXT_STEPS.subtitle}</p>
        
        <div className="steps-grid">
          {NEXT_STEPS.steps.map((step, index) => (
            <div key={index} className="step-card">
              <div className="step-number">{index + 1}</div>
              <div className="step-icon">{getStepIcon(step.icon)}</div>
              <h3>{step.title}</h3>
              <p>{step.description}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default NextSteps;

